for i in range(1, n + 1):
    for j in range(i, n + 1, i):
        count += 1', '["O(n)", "O(n log n)", "O(n√n)", "O(n²)"]', 'B', 'Pour un i donné, la boucle interne tourne n / i fois.', 'Total : n/1 + n/2 + n/3 + … + n/n = n·(1 + 1/2 + … + 1/n) ≈ n·ln n. Cette série harmonique apparaît dans les cribles : O(n log n).', 'harmonic series', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'python', 'Shrinking work', 'What is the time complexity of f(n)?', 'def f(n):
    if n <= 1:
        return 0
    s = 0
    for i in range(n):
        s += i
    return s + f(n // 2)', '["O(log n)", "O(n)", "O(n log n)", "O(n²)"]', 'B', 'Add up the loop sizes: n + n/2 + n/4 + …', 'T(n) = T(n/2) + O(n). The work is n + n/2 + n/4 + … ≤ 2n, a geometric series, so O(n), not O(n log n).', 'recurrences', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'python', 'Travail qui fond', 'Quelle est la complexité de f(n) ?', 'def f(n):
    if n <= 1:
        return 0
    s = 0
    for i in range(n):
        s += i
    return s + f(n // 2)', '["O(log n)", "O(n)", "O(n log n)", "O(n²)"]', 'B', 'Additionne les tailles des boucles : n + n/2 + n/4 + …', 'T(n) = T(n/2) + O(n). Le travail vaut n + n/2 + n/4 + … ≤ 2n, une série géométrique : O(n), et non O(n log n).', 'recurrences', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'python', 'Cached branches', 'What is the time complexity of the first call ways(n)? (count arithmetic as O(1))', 'from functools import lru_cache

@lru_cache(None)
def ways(n):
    if n < 0:
        return 0
    if n == 0:
        return 1
    return ways(n - 1) + ways(n - 2) + ways(n - 3)', '["O(3ⁿ)", "O(n)", "O(n³)", "O(n log n)"]', 'B', 'How many different arguments can ways be called with?', 'Each distinct n is computed once and then served from the cache. There are about n distinct arguments, each doing O(1) work: O(n). Without the cache it would be about O(1.84ⁿ).', 'memoization', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'python', 'Branches en cache', 'Quelle est la complexité du premier appel ways(n) ? (on compte l''arithmétique en O(1))', 'from functools import lru_cache

@lru_cache(None)
def ways(n):
    if n < 0:
        return 0
    if n == 0:
        return 1
    return ways(n - 1) + ways(n - 2) + ways(n - 3)', '["O(3ⁿ)", "O(n)", "O(n³)", "O(n log n)"]', 'B', 'Avec combien d''arguments différents ways peut-elle être appelée ?', 'Chaque n distinct est calculé une fois puis servi par le cache. Il y a environ n arguments distincts, chacun en O(1) : O(n). Sans le cache, ce serait environ O(1,84ⁿ).', 'memoization', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'python', 'Two pointers', 'What is the time complexity?', 'i = 0
for j in range(n):
    while i < j and a[i] + a[j] > limit:
        i += 1', '["O(n)", "O(n log n)", "O(n²)", "O(n²) only if a is sorted"]', 'A', 'How many times can `i += 1` run in total, over the whole loop?', 'i only moves forward and never exceeds n, so the while loop runs at most n times IN TOTAL across all j. Amortized: O(n).', 'two pointers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'python', 'Deux pointeurs', 'Quelle est la complexité ?', 'i = 0
