INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'python', 'Front of the line', 'What is the time complexity?', 'q = list(range(n))
