    x = q.pop(0)', '["O(n)", "O(n log n)", "O(n²)", "O(1) amortized per pop, so O(n)"]', 'C', 'What does Python have to do with the other elements when the first one is removed?', 'pop(0) shifts every remaining element one place left: O(k) for a list of k elements. n + (n-1) + … + 1 = O(n²). collections.deque.popleft() is O(1).', 'lists', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'python', 'Tête de file', 'Quelle est la complexité ?', 'q = list(range(n))
