INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'javascript', 'Double or triple?', 'What does this code print? (both lines)', 'console.log(1 == "1", 1 === "1", null == undefined, null === undefined);
console.log(NaN === NaN, [1] == 1);', NULL, 'true false true false
false true', '`==` converts types before comparing, `===` never does. NaN is special.', '`==` converts "1" to 1 and [1] to "1" then 1, so both are true. `===` compares type too. null == undefined is a special rule, but they are different types. NaN is never equal to anything, not even itself.', 'equality', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'javascript', 'Double ou triple ?', 'Qu''affiche ce code ? (les deux lignes)', 'console.log(1 == "1", 1 === "1", null == undefined, null === undefined);
console.log(NaN === NaN, [1] == 1);', NULL, 'true false true false
false true', '`==` convertit les types avant de comparer, `===` jamais. NaN est un cas spécial.', '`==` convertit "1" en 1 et [1] en "1" puis 1 : les deux sont vrais. `===` compare aussi le type. null == undefined est une règle spéciale, mais ce sont deux types différents. NaN n''est égal à rien, même pas à lui-même.', 'equality', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'javascript', 'Same box?', 'What does this code print?', 'const a = [1, 2, 3];
const b = a;
const c = [...a];
b.push(4);
c.push(5);
console.log(a.length, b.length, c.length, a === b);', NULL, '4 4 4 true', 'Assigning an array copies the reference; spreading creates a new array.', 'b is the same array as a, so push(4) changes both: length 4. [...a] makes a new array of 3, then 5 is added: length 4. a === b compares references: true.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'javascript', 'Même boîte ?', 'Qu''affiche ce code ?', 'const a = [1, 2, 3];
const b = a;
const c = [...a];
b.push(4);
c.push(5);
console.log(a.length, b.length, c.length, a === b);', NULL, '4 4 4 true', 'Affecter un tableau copie la référence ; le spread crée un nouveau tableau.', 'b est le même tableau que a, donc push(4) modifie les deux : longueur 4. [...a] crée un nouveau tableau de 3, puis on ajoute 5 : longueur 4. a === b compare les références : true.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'javascript', 'Cut and count', 'What does this code print?', 'const s = "JavaScript";
console.log(s.slice(-6, -2), s.indexOf("a", 2), s.split("a").length);', NULL, 'Scri 3 3', 'Negative slice indexes count from the end. indexOf''s second argument is where the search starts.', 'Length 10: slice(-6, -2) is slice(4, 8) = "Scri". The first "a" at index ≥ 2 is at 3. Splitting on the two "a" gives 3 pieces: "J", "v", "Script".', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'javascript', 'Couper et compter', 'Qu''affiche ce code ?', 'const s = "JavaScript";
