INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'javascript', 'Skip and stop', 'What does this code print?', 'let out = "";
