INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'en', 'javascript', 'Declare it right', 'Which statement about `var`, `let` and `const` is true?', NULL, '["`var` cannot be reassigned", "`let` is visible in the whole function", "`const` must be initialized when declared, and can''t be reassigned", "`let` and `var` are exactly the same"]', 'C', 'Try `const x;` in your head. And remember `var` is the old one.', '`const` needs a value immediately and the binding can''t be reassigned (an object it points to can still change). `var` is function-scoped and reassignable; `let` is block-scoped.', 'variables', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'fr', 'javascript', 'Bien déclarer', 'Quelle affirmation sur `var`, `let` et `const` est vraie ?', NULL, '["`var` ne peut pas être réaffectée", "`let` est visible dans toute la fonction", "`const` doit être initialisée à la déclaration et ne peut pas être réaffectée", "`let` et `var` sont exactement pareils"]', 'C', 'Essaie `const x;` dans ta tête. Et `var` est l''ancienne façon.', '`const` exige une valeur tout de suite et ne peut pas être réaffectée (un objet pointé peut encore changer). `var` a une portée de fonction et se réaffecte ; `let` a une portée de bloc.', 'variables', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'en', 'javascript', 'What type is it?', 'Which expression is `true`?', NULL, '["`typeof null === \"null\"`", "`typeof [] === \"object\"`", "`typeof NaN === \"NaN\"`", "`typeof function(){} === \"object\"`"]', 'B', 'JavaScript has only a few typeof answers: "number", "string", "boolean", "undefined", "object", "function", "symbol", "bigint".', 'Arrays are objects, so typeof [] is "object" (use Array.isArray). typeof null is also "object" (a historic bug), NaN is a "number", and functions are "function".', 'types', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'fr', 'javascript', 'Quel type ?', 'Quelle expression vaut `true` ?', NULL, '["`typeof null === \"null\"`", "`typeof [] === \"object\"`", "`typeof NaN === \"NaN\"`", "`typeof function(){} === \"object\"`"]', 'B', 'typeof n''a que quelques réponses : "number", "string", "boolean", "undefined", "object", "function", "symbol", "bigint".', 'Les tableaux sont des objets, donc typeof [] vaut "object" (utilise Array.isArray). typeof null vaut aussi "object" (un vieux bug), NaN est un "number", et une fonction donne "function".', 'types', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'en', 'javascript', 'Inner loop, fixed size', 'With n = arr.length, what is the time complexity of `f`?', 'function f(arr) {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < 5; j++) {
      count += arr[i] * j;
    }
  }
  return count;
}', '["O(1)", "O(log n)", "O(n)", "O(n²)"]', 'C', 'How many times does the inner loop run, and does it depend on n?', 'The inner loop always runs 5 times, a constant. The total is 5·n steps, which is O(n). Two nested loops are only O(n²) when both depend on n.', 'loops', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'fr', 'javascript', 'Boucle interne fixe', 'Avec n = arr.length, quelle est la complexité de `f` ?', 'function f(arr) {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < 5; j++) {
      count += arr[i] * j;
    }
  }
  return count;
}', '["O(1)", "O(log n)", "O(n)", "O(n²)"]', 'C', 'Combien de tours fait la boucle interne, et dépend-elle de n ?', 'La boucle interne fait toujours 5 tours, une constante. Le total est 5·n, donc O(n). Deux boucles imbriquées ne font O(n²) que si les deux dépendent de n.', 'loops', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'en', 'javascript', 'Seen it before', 'What is the worst-case time complexity of `hasDuplicate` for an array of n elements?', 'function hasDuplicate(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}', '["O(n²)", "O(n)", "O(n log n)", "O(1)"]', 'B', 'What does a Set lookup cost on average?', 'Set.has and Set.add take constant time on average, and each element is visited once: O(n). With `arr.includes` inside the loop instead, it would be O(n²).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'fr', 'javascript', 'Déjà vu', 'Quelle est la complexité dans le pire cas de `hasDuplicate` pour un tableau de n éléments ?', 'function hasDuplicate(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}', '["O(n²)", "O(n)", "O(n log n)", "O(1)"]', 'B', 'Combien coûte une recherche dans un Set en moyenne ?', 'Set.has et Set.add sont en temps constant en moyenne, et chaque élément est vu une fois : O(n). Avec `arr.includes` dans la boucle, ce serait O(n²).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'en', 'javascript', 'Average trouble', '`average([2, 4, 6])` should print 4. What actually goes wrong?', 'function average(nums) {
  let total = 0;
  for (let i = 0; i <= nums.length; i++) {
    total += nums[i];
  }
  return total / nums.length;
}
console.log(average([2, 4, 6]));', '["`i <= nums.length` reads one element too far: `nums[3]` is `undefined`, so the total becomes `NaN`", "`total` must be declared with `const`", "Division by `nums.length` is integer division in JavaScript", "`let i` is not visible inside the loop"]', 'A', 'What is the last index of an array of length 3?', 'Valid indexes are 0..length-1. With `<=` the loop also adds nums[3], which is undefined, and 12 + undefined is NaN. Use `i < nums.length`.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'fr', 'javascript', 'Moyenne en panne', '`average([2, 4, 6])` devrait afficher 4. Qu''est-ce qui se passe vraiment ?', 'function average(nums) {
  let total = 0;
  for (let i = 0; i <= nums.length; i++) {
    total += nums[i];
  }
  return total / nums.length;
}
console.log(average([2, 4, 6]));', '["`i <= nums.length` lit un élément de trop : `nums[3]` vaut `undefined`, donc le total devient `NaN`", "`total` doit être déclaré avec `const`", "La division par `nums.length` est entière en JavaScript", "`let i` n''est pas visible dans la boucle"]', 'A', 'Quel est le dernier indice d''un tableau de longueur 3 ?', 'Les indices valides vont de 0 à length-1. Avec `<=`, la boucle ajoute aussi nums[3], qui vaut undefined, et 12 + undefined donne NaN. Utilise `i < nums.length`.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'en', 'javascript', 'Big first letter', '`capitalize("hello")` should return "Hello". What is wrong?', 'function capitalize(word) {
  word[0] = word[0].toUpperCase();
  return word;
}
console.log(capitalize("hello"));', '["`toUpperCase` only works on whole strings", "The function needs `return word[0]`", "Strings are immutable: assigning `word[0]` silently does nothing, so \"hello\" comes back unchanged", "`word[0]` is undefined for strings"]', 'C', 'Can you change one character of a string in place?', 'JavaScript strings can''t be modified. `word[0] = ...` is ignored (outside strict mode) and the original string is returned. Build a new one: `word[0].toUpperCase() + word.slice(1)`.', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'fr', 'javascript', 'Grande première lettre', '`capitalize("hello")` devrait renvoyer "Hello". Qu''est-ce qui ne va pas ?', 'function capitalize(word) {
  word[0] = word[0].toUpperCase();
  return word;
}
console.log(capitalize("hello"));', '["`toUpperCase` ne marche que sur des chaînes entières", "La fonction doit faire `return word[0]`", "Les chaînes sont immuables : affecter `word[0]` ne fait rien, \"hello\" revient inchangé", "`word[0]` vaut undefined pour une chaîne"]', 'C', 'Peut-on modifier un caractère d''une chaîne sur place ?', 'Les chaînes JavaScript ne se modifient pas. `word[0] = ...` est ignoré (hors mode strict) et la chaîne d''origine est renvoyée. Crée une nouvelle chaîne : `word[0].toUpperCase() + word.slice(1)`.', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'javascript', 'var vs let in loops', 'What does this code print?', 'const fns = [];
for (var i = 0; i < 3; i++) fns.push(() => i);
const gns = [];
for (let j = 0; j < 3; j++) gns.push(() => j);
console.log(fns.map(f => f()).join(","), gns.map(g => g()).join(","));', NULL, '3,3,3 0,1,2', 'How many `i` variables exist? How many `j`?', '`var i` is one variable shared by every arrow function; when they run, the loop is over and i is 3. `let j` creates a fresh binding for each iteration, so each function remembers its own j.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'javascript', 'var ou let dans les boucles', 'Qu''affiche ce code ?', 'const fns = [];
for (var i = 0; i < 3; i++) fns.push(() => i);
const gns = [];
for (let j = 0; j < 3; j++) gns.push(() => j);
console.log(fns.map(f => f()).join(","), gns.map(g => g()).join(","));', NULL, '3,3,3 0,1,2', 'Combien de variables `i` existent ? Combien de `j` ?', '`var i` est une seule variable partagée par toutes les fonctions ; quand elles s''exécutent, la boucle est finie et i vaut 3. `let j` crée une nouvelle liaison à chaque tour : chaque fonction garde son propre j.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'javascript', 'Sort it out', 'What does this code print? (both lines)', 'const a = [10, 9, 1, 100, 25];
const b = [...a].sort();
const c = [...a].sort((x, y) => x - y);
console.log(b.join(" "));
console.log(c.join(" "));', NULL, '1 10 100 25 9
1 9 10 25 100', 'Without a compare function, sort() converts the elements to strings.', 'The default sort compares strings: "1" < "10" < "100" < "25" < "9". With (x, y) => x - y the numbers are compared as numbers.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'javascript', 'Faire le tri', 'Qu''affiche ce code ? (les deux lignes)', 'const a = [10, 9, 1, 100, 25];
const b = [...a].sort();
const c = [...a].sort((x, y) => x - y);
console.log(b.join(" "));
console.log(c.join(" "));', NULL, '1 10 100 25 9
1 9 10 25 100', 'Sans fonction de comparaison, sort() convertit les éléments en chaînes.', 'Le tri par défaut compare des chaînes : "1" < "10" < "100" < "25" < "9". Avec (x, y) => x - y, les nombres sont comparés comme des nombres.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'javascript', 'Shallow copy', 'What does this code print?', 'const user = { name: "Ana", tags: ["a"] };
const copy = { ...user };
copy.name = "Bo";
copy.tags.push("b");
const { name, tags: [first, second = "none"] } = user;
console.log(name, first, second, user.tags.length);', NULL, 'Ana a b 2', 'The spread copies the first level only. Then follow the destructuring carefully.', '{ ...user } copies the properties, but tags is still the same array, so push("b") also changes user.tags. user.name stays "Ana". Destructuring gives first = "a" and second = "b" (the default is not used because there is a value).', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'javascript', 'Copie superficielle', 'Qu''affiche ce code ?', 'const user = { name: "Ana", tags: ["a"] };
const copy = { ...user };
copy.name = "Bo";
copy.tags.push("b");
const { name, tags: [first, second = "none"] } = user;
console.log(name, first, second, user.tags.length);', NULL, 'Ana a b 2', 'Le spread ne copie que le premier niveau. Suis ensuite la déstructuration avec soin.', '{ ...user } copie les propriétés, mais tags est toujours le même tableau : push("b") modifie aussi user.tags. user.name reste "Ana". La déstructuration donne first = "a" et second = "b" (la valeur par défaut n''est pas utilisée car il y a une valeur).', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'javascript', 'map(parseInt)', 'What does this code print?', 'const r = ["1", "2", "3", "10"].map(parseInt);
const s = [1, 2, 3, 4].reduce((acc, x) => acc + (x % 2 ? x : -x), 10);
console.log(r.join(" "), s);', NULL, '1 NaN NaN 3 8', 'map calls its function with (element, index, array). What is parseInt''s second parameter?', 'parseInt receives the index as the radix: parseInt("1", 0) = 1 (radix 0 means 10), parseInt("2", 1) = NaN (radix 1 is invalid), parseInt("3", 2) = NaN (3 is not a binary digit), parseInt("10", 3) = 3. The reduce does 10 + 1 - 2 + 3 - 4 = 8.', 'higher-order functions', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'javascript', 'map(parseInt)', 'Qu''affiche ce code ?', 'const r = ["1", "2", "3", "10"].map(parseInt);
const s = [1, 2, 3, 4].reduce((acc, x) => acc + (x % 2 ? x : -x), 10);
console.log(r.join(" "), s);', NULL, '1 NaN NaN 3 8', 'map appelle sa fonction avec (élément, indice, tableau). Quel est le 2e paramètre de parseInt ?', 'parseInt reçoit l''indice comme base : parseInt("1", 0) = 1 (base 0 signifie 10), parseInt("2", 1) = NaN (base 1 invalide), parseInt("3", 2) = NaN (3 n''est pas un chiffre binaire), parseInt("10", 3) = 3. Le reduce fait 10 + 1 - 2 + 3 - 4 = 8.', 'higher-order functions', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'en', 'javascript', 'What does await do?', 'Which statement about `async`/`await` is true?', NULL, '["`await` blocks the whole program until the promise settles", "An `async` function returns its value directly, not a promise", "`setTimeout(f, 0)` runs `f` immediately, before the next line", "`await` pauses only the current async function; other code keeps running"]', 'D', 'Think of the event loop: is there one thread or many?', '`await` suspends only the async function it is in; the caller continues and the function resumes later from the microtask queue. An async function always returns a promise, and setTimeout callbacks run after the current code finishes.', 'asynchronous', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'fr', 'javascript', 'Que fait await ?', 'Quelle affirmation sur `async`/`await` est vraie ?', NULL, '["`await` bloque tout le programme jusqu''à la fin de la promesse", "Une fonction `async` renvoie sa valeur directement, pas une promesse", "`setTimeout(f, 0)` exécute `f` immédiatement, avant la ligne suivante", "`await` met en pause seulement la fonction async en cours ; le reste du code continue"]', 'D', 'Pense à la boucle d''événements : un seul fil ou plusieurs ?', '`await` suspend seulement la fonction async où il se trouve ; l''appelant continue et la fonction reprend plus tard via la file des micro-tâches. Une fonction async renvoie toujours une promesse, et les callbacks de setTimeout passent après le code en cours.', 'asynchronous', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'en', 'javascript', 'Who is this?', 'Which statement about `this` is true?', NULL, '["Arrow functions get `this` from the object that calls them", "Arrow functions don''t have their own `this`: they use the `this` of the surrounding code", "`this` inside a regular function always refers to the function itself", "`bind` changes `this` for arrow functions"]', 'B', 'Arrow functions were designed to keep the outer `this`, for example inside callbacks.', 'An arrow function has no `this` of its own; it uses the `this` where it was defined, and even bind/call can''t change it. A regular function''s `this` depends on how it is called (o.reg() vs f()).', 'this', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'fr', 'javascript', 'Qui est this ?', 'Quelle affirmation sur `this` est vraie ?', NULL, '["Les fonctions fléchées prennent `this` de l''objet qui les appelle", "Les fonctions fléchées n''ont pas leur propre `this` : elles utilisent celui du code qui les entoure", "Dans une fonction classique, `this` désigne toujours la fonction elle-même", "`bind` change le `this` des fonctions fléchées"]', 'B', 'Les fonctions fléchées ont été conçues pour garder le `this` extérieur, par exemple dans les callbacks.', 'Une fonction fléchée n''a pas son propre `this` : elle utilise le `this` de l''endroit où elle est définie, et même bind/call ne le changent pas. Le `this` d''une fonction classique dépend de la façon dont on l''appelle (o.reg() ou f()).', 'this', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'en', 'javascript', 'includes in a loop', 'Worst case, with n = arr.length (all values different), what is the time complexity?', 'function uniqueSorted(arr) {
  const out = [];
  for (const x of arr) {
    if (!out.includes(x)) out.push(x);
  }
  return out.sort((a, b) => a - b);
}', '["O(n)", "O(n log n)", "O(n²)", "O(n² log n)"]', 'C', '`includes` scans the array it''s called on. How big does `out` get?', 'When every value is new, out grows to n elements and each `includes` scans all of it: 0 + 1 + … + (n-1) ≈ n²/2 steps. The final sort is O(n log n), which is smaller. Total: O(n²). A Set would make it O(n log n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'fr', 'javascript', 'includes dans une boucle', 'Dans le pire cas, avec n = arr.length (toutes les valeurs différentes), quelle est la complexité ?', 'function uniqueSorted(arr) {
  const out = [];
  for (const x of arr) {
    if (!out.includes(x)) out.push(x);
  }
  return out.sort((a, b) => a - b);
}', '["O(n)", "O(n log n)", "O(n²)", "O(n² log n)"]', 'C', '`includes` parcourt le tableau sur lequel on l''appelle. Quelle taille atteint `out` ?', 'Si chaque valeur est nouvelle, out atteint n éléments et chaque `includes` le parcourt entièrement : 0 + 1 + … + (n-1) ≈ n²/2 étapes. Le tri final est en O(n log n), plus petit. Total : O(n²). Un Set donnerait O(n log n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'en', 'javascript', 'Doubling inside', 'What is the time complexity of `countPairs`?', 'function countPairs(s) {
  // s has n characters
  let pairs = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j < s.length; j *= 2) {
      if (s[i] === s[j]) pairs++;
    }
  }
  return pairs;
}', '["O(n²)", "O(n log n)", "O(n)", "O(log n)"]', 'B', 'How many values does j take when it doubles each time, up to n?', 'For each i, j goes i+1, 2(i+1), 4(i+1)… until n: at most about log₂ n steps. n outer turns × log n inner turns = O(n log n).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'fr', 'javascript', 'Doublement à l''intérieur', 'Quelle est la complexité de `countPairs` ?', 'function countPairs(s) {
  // s has n characters
  let pairs = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j < s.length; j *= 2) {
      if (s[i] === s[j]) pairs++;
    }
  }
  return pairs;
}', '["O(n²)", "O(n log n)", "O(n)", "O(log n)"]', 'B', 'Combien de valeurs prend j s''il double à chaque tour jusqu''à n ?', 'Pour chaque i, j vaut i+1, 2(i+1), 4(i+1)… jusqu''à n : au plus environ log₂ n étapes. n tours extérieurs × log n tours intérieurs = O(n log n).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'en', 'javascript', 'Empty results', '`loadAll([1, 2, 3])` returns an empty array. Why?', 'function loadAll(ids) {
  const results = [];
  ids.forEach(async (id) => {
    const value = await fetchValue(id);   // returns a promise
    results.push(value);
  });
  return results;
}', '["`fetchValue` must be called without `await`", "`forEach` doesn''t wait for async callbacks: `results` is returned before any `await` finishes", "`results` is a `const`, so `push` fails silently", "Arrow functions can''t be `async`"]', 'B', 'What does forEach do with the promise each callback returns?', 'forEach ignores the promises returned by the async callbacks; it finishes immediately and the function returns the still-empty array. Use `return Promise.all(ids.map(fetchValue))` in an async function, or a `for...of` loop with await.', 'asynchronous', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'fr', 'javascript', 'Résultats vides', '`loadAll([1, 2, 3])` renvoie un tableau vide. Pourquoi ?', 'function loadAll(ids) {
  const results = [];
  ids.forEach(async (id) => {
    const value = await fetchValue(id);   // returns a promise
    results.push(value);
  });
  return results;
}', '["`fetchValue` doit être appelée sans `await`", "`forEach` n''attend pas les callbacks async : `results` est renvoyé avant la fin de chaque `await`", "`results` est un `const`, donc `push` échoue sans rien dire", "Les fonctions fléchées ne peuvent pas être `async`"]', 'B', 'Que fait forEach de la promesse renvoyée par chaque callback ?', 'forEach ignore les promesses renvoyées par les callbacks async ; il se termine tout de suite et la fonction renvoie le tableau encore vide. Utilise `return Promise.all(ids.map(fetchValue))` dans une fonction async, ou une boucle `for...of` avec await.', 'asynchronous', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'en', 'javascript', 'Floating money', '`total([0.1, 0.2, 0.3])` prints "wrong". Why?', 'function total(prices) {
  let sum = 0;
  for (const p of prices) sum += p;
  return sum === 0.6 ? "exact" : "wrong";
}
console.log(total([0.1, 0.2, 0.3]));', '["Decimal numbers are stored in binary floating point, so the sum is 0.6000000000000001, not exactly 0.6", "`for...of` skips the last element", "`===` can''t compare numbers", "`sum` starts at 0 instead of 0.0"]', 'A', 'Try 0.1 + 0.2 in the console.', '0.1, 0.2 and 0.3 have no exact binary representation, so the sum is 0.6000000000000001. Compare with a tolerance (`Math.abs(a - b) < 1e-9`) or work in cents with integers.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'fr', 'javascript', 'Argent flottant', '`total([0.1, 0.2, 0.3])` affiche "wrong". Pourquoi ?', 'function total(prices) {
  let sum = 0;
  for (const p of prices) sum += p;
  return sum === 0.6 ? "exact" : "wrong";
}
console.log(total([0.1, 0.2, 0.3]));', '["Les décimaux sont stockés en virgule flottante binaire : la somme vaut 0.6000000000000001, pas exactement 0.6", "`for...of` saute le dernier élément", "`===` ne peut pas comparer des nombres", "`sum` commence à 0 au lieu de 0.0"]', 'A', 'Essaie 0.1 + 0.2 dans la console.', '0.1, 0.2 et 0.3 n''ont pas de représentation binaire exacte : la somme vaut 0.6000000000000001. Compare avec une tolérance (`Math.abs(a - b) < 1e-9`) ou calcule en centimes avec des entiers.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'en', 'javascript', 'Word count surprise', '`countWords("the constructor")` should give `{ the: 1, constructor: 1 }`, but `counts.constructor` is a strange string. What is the real problem?', 'function countWords(text) {
  const counts = {};
  for (const w of text.split(" ")) {
    counts[w] = counts[w] + 1 || 1;
  }
  return counts;
}
console.log(countWords("constructor of the class").constructor);', '["`split(\" \")` keeps the spaces", "`|| 1` should be `?? 1`", "Objects can''t have more than one key", "A plain `{}` inherits keys like `constructor` from `Object.prototype`, so `counts[\"constructor\"]` already exists: use a `Map` or `Object.create(null)`"]', 'D', 'Is `counts["constructor"]` really undefined before the first word?', '{} has a prototype, so counts.constructor is the Object function. Adding 1 concatenates its source code with "1". Words like constructor, toString or __proto__ break plain-object counters; a Map (or Object.create(null)) has no inherited keys.', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'fr', 'javascript', 'Comptage surprise', '`countWords("the constructor")` devrait donner `{ the: 1, constructor: 1 }`, mais `counts.constructor` est une chaîne bizarre. Quel est le vrai problème ?', 'function countWords(text) {
  const counts = {};
  for (const w of text.split(" ")) {
    counts[w] = counts[w] + 1 || 1;
  }
  return counts;
}
console.log(countWords("constructor of the class").constructor);', '["`split(\" \")` garde les espaces", "`|| 1` devrait être `?? 1`", "Un objet ne peut pas avoir plus d''une clé", "Un `{}` hérite de clés comme `constructor` depuis `Object.prototype`, donc `counts[\"constructor\"]` existe déjà : utilise une `Map` ou `Object.create(null)`"]', 'D', '`counts["constructor"]` vaut-il vraiment undefined avant le premier mot ?', '{} a un prototype, donc counts.constructor est la fonction Object. Lui ajouter 1 concatène son code source avec "1". Des mots comme constructor, toString ou __proto__ cassent les compteurs en objet simple ; une Map (ou Object.create(null)) n''a pas de clés héritées.', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'javascript', 'Event loop order', 'What does this code print?', 'const log = [];
setTimeout(() => log.push("timeout"), 0);
Promise.resolve().then(() => log.push("micro1")).then(() => log.push("micro2"));
(async () => {
  log.push("async-start");
  await null;
  log.push("after-await");
})();
queueMicrotask(() => log.push("qm"));
log.push("sync");
setTimeout(() => console.log(log.join(" ")), 10);', NULL, 'async-start sync micro1 after-await qm micro2 timeout', 'Synchronous code first, then ALL microtasks (in the order they were queued, including new ones), then timers.', 'Sync: async-start (the async body runs immediately until await), then sync. Microtasks in queue order: micro1, after-await, qm; micro1''s then queues micro2, which runs before any timer. Then the timeout.', 'event loop', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'javascript', 'Ordre de la boucle d''événements', 'Qu''affiche ce code ?', 'const log = [];
setTimeout(() => log.push("timeout"), 0);
Promise.resolve().then(() => log.push("micro1")).then(() => log.push("micro2"));
(async () => {
  log.push("async-start");
  await null;
  log.push("after-await");
})();
queueMicrotask(() => log.push("qm"));
log.push("sync");
setTimeout(() => console.log(log.join(" ")), 10);', NULL, 'async-start sync micro1 after-await qm micro2 timeout', 'D''abord le code synchrone, puis TOUTES les micro-tâches (dans l''ordre, y compris les nouvelles), puis les timers.', 'Synchrone : async-start (le corps async s''exécute jusqu''au await), puis sync. Micro-tâches dans l''ordre : micro1, after-await, qm ; le then de micro1 ajoute micro2, qui passe avant tout timer. Puis le timeout.', 'event loop', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'javascript', 'Hoisted', 'What does this code print? (3 lines)', 'var x = 1;
function f() {
  console.log(x);
  if (false) { var x = 2; }
  return typeof g + " " + typeof h;
  function g() {}
  var h = function () {};
}
console.log(f());
try { console.log(y); let y = 3; } catch (e) { console.log(e.name); }', NULL, 'undefined
function undefined
ReferenceError', '`var` declarations and function declarations are moved to the top of their function. `let` is in a temporal dead zone until its line.', 'Inside f, `var x` is hoisted (even in an `if (false)`), so the local x shadows the global one and is undefined. g is a hoisted function declaration; h is declared but the assignment never runs (after return), so it''s undefined. Reading y before `let y` throws a ReferenceError.', 'hoisting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'javascript', 'Remontée', 'Qu''affiche ce code ? (3 lignes)', 'var x = 1;
function f() {
  console.log(x);
  if (false) { var x = 2; }
  return typeof g + " " + typeof h;
  function g() {}
  var h = function () {};
}
console.log(f());
try { console.log(y); let y = 3; } catch (e) { console.log(e.name); }', NULL, 'undefined
function undefined
ReferenceError', 'Les déclarations `var` et les déclarations de fonctions remontent en haut de leur fonction. `let` est en zone morte temporaire jusqu''à sa ligne.', 'Dans f, `var x` est remontée (même dans un `if (false)`), donc le x local masque le global et vaut undefined. g est une déclaration de fonction remontée ; h est déclarée mais l''affectation n''a jamais lieu (après le return) : undefined. Lire y avant `let y` lève une ReferenceError.', 'hoisting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'javascript', 'Talking to a generator', 'What does this code print?', 'function* counter() {
  let n = 0;
  while (true) {
    const reset = yield n++;
    if (reset) n = 10;
  }
}
const it = counter();
const out = [it.next().value, it.next().value, it.next(true).value, it.next().value];
const [a, , b] = counter();
console.log(out.join(","), a, b);', NULL, '0,1,10,11 0 2', 'The value passed to next(v) becomes the result of the `yield` where the generator is paused. Destructuring also pulls values from an iterator.', 'next() → 0, next() → 1 (n is now 2), next(true): the paused yield returns true so n becomes 10, then it yields 10 (n is 11), next() → 11. Destructuring takes values 0, 1, 2 and keeps the 1st and 3rd: 0 and 2.', 'generators', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'javascript', 'Parler à un générateur', 'Qu''affiche ce code ?', 'function* counter() {
  let n = 0;
  while (true) {
    const reset = yield n++;
    if (reset) n = 10;
  }
}
const it = counter();
const out = [it.next().value, it.next().value, it.next(true).value, it.next().value];
const [a, , b] = counter();
console.log(out.join(","), a, b);', NULL, '0,1,10,11 0 2', 'La valeur passée à next(v) devient le résultat du `yield` où le générateur est en pause. La déstructuration lit aussi un itérateur.', 'next() → 0, next() → 1 (n vaut 2), next(true) : le yield en pause renvoie true donc n devient 10, puis il produit 10 (n vaut 11), next() → 11. La déstructuration prend 0, 1, 2 et garde le 1er et le 3e : 0 et 2.', 'generators', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'javascript', 'Coercion madness', 'What does this code print? (2 lines)', 'console.log([] + {}, [1, 2] + [3], true + "1" - 1);
console.log([10, 1, 3].sort() + "", ("b" + "a" + +"a" + "a").toLowerCase());', NULL, '[object Object] 1,23 NaN
1,10,3 banana', '`+` with a string or object concatenates; `-` and unary `+` always convert to numbers.', '[] + {} → "" + "[object Object]". [1, 2] + [3] → "1,2" + "3" = "1,23". true + "1" is "true1", minus 1 is NaN. Default sort is by string: 1, 10, 3. +"a" is NaN, so the word becomes "baNaNa", lowercased "banana".', 'coercion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'javascript', 'Folie des conversions', 'Qu''affiche ce code ? (2 lignes)', 'console.log([] + {}, [1, 2] + [3], true + "1" - 1);
console.log([10, 1, 3].sort() + "", ("b" + "a" + +"a" + "a").toLowerCase());', NULL, '[object Object] 1,23 NaN
1,10,3 banana', '`+` avec une chaîne ou un objet concatène ; `-` et le `+` unaire convertissent toujours en nombre.', '[] + {} → "" + "[object Object]". [1, 2] + [3] → "1,2" + "3" = "1,23". true + "1" donne "true1", moins 1 donne NaN. Le tri par défaut est textuel : 1, 10, 3. +"a" vaut NaN, donc le mot devient "baNaNa", en minuscules "banana".', 'coercion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'en', 'javascript', 'Under the class', 'With `class Animal { speak() {} }`, `class Dog extends Animal {}` and `const d = new Dog()`, which statement is true?', NULL, '["`Object.getPrototypeOf(d) === Dog.prototype`, and `speak` is found on `Animal.prototype` through the chain", "`speak` is copied into `d` when it is created", "`class Dog extends Animal` copies every method of Animal into Dog", "`d.hasOwnProperty(\"speak\")` is `true`"]', 'A', 'Classes are syntax over prototypes. Where do methods live?', 'Methods live on the prototype objects, not on instances or subclasses. d → Dog.prototype → Animal.prototype (which has speak) → Object.prototype. Nothing is copied, so d has no own `speak`.', 'prototypes', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'fr', 'javascript', 'Sous la classe', 'Avec `class Animal { speak() {} }`, `class Dog extends Animal {}` et `const d = new Dog()`, quelle affirmation est vraie ?', NULL, '["`Object.getPrototypeOf(d) === Dog.prototype`, et `speak` est trouvée sur `Animal.prototype` via la chaîne", "`speak` est copiée dans `d` à sa création", "`class Dog extends Animal` copie toutes les méthodes d''Animal dans Dog", "`d.hasOwnProperty(\"speak\")` vaut `true`"]', 'A', 'Les classes sont une syntaxe au-dessus des prototypes. Où vivent les méthodes ?', 'Les méthodes vivent sur les objets prototypes, pas sur les instances ni les sous-classes. d → Dog.prototype → Animal.prototype (qui a speak) → Object.prototype. Rien n''est copié : d n''a pas de `speak` propre.', 'prototypes', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'en', 'javascript', 'All or nothing', 'Which statement about `Promise.all` is true?', NULL, '["`Promise.all` returns the results in the order the promises finish", "`Promise.all` waits for every promise, even after one rejects, and then rejects", "`Promise.all` rejects as soon as one promise rejects, but the other promises keep running", "`Promise.allSettled` rejects if any promise rejects"]', 'C', 'A promise can''t be cancelled.', 'Promise.all rejects with the first rejection, immediately, but nothing stops the other operations: they finish in the background. When everything succeeds, results keep the input order, not the finishing order. allSettled never rejects.', 'promises', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'fr', 'javascript', 'Tout ou rien', 'Quelle affirmation sur `Promise.all` est vraie ?', NULL, '["`Promise.all` renvoie les résultats dans l''ordre où les promesses se terminent", "`Promise.all` attend toutes les promesses, même après un rejet, puis échoue", "`Promise.all` est rejetée dès qu''une promesse échoue, mais les autres continuent de s''exécuter", "`Promise.allSettled` est rejetée si une promesse échoue"]', 'C', 'Une promesse ne peut pas être annulée.', 'Promise.all est rejetée dès le premier rejet, mais rien n''arrête les autres opérations : elles se terminent en arrière-plan. Quand tout réussit, les résultats gardent l''ordre d''entrée, pas l''ordre de fin. allSettled n''est jamais rejetée.', 'promises', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'javascript', 'Hidden costs', 'What is the time complexity of `build(n)`?', 'function build(n) {
  let s = "";
  const parts = [];
  for (let i = 0; i < n; i++) {
    parts.unshift(String(i % 10));   // add at the front
  }
  for (let i = 0; i < n; i++) {
    s = parts.slice(0, i).join("").length + s.slice(0, 1);
  }
  return s;
}', '["O(n)", "O(n log n)", "O(n²) for the first loop only", "O(n²): both loops are quadratic"]', 'D', 'What does `unshift` do to the other elements? What does `slice(0, i).join("")` cost?', 'unshift shifts every existing element one place: 1 + 2 + … + n = O(n²). In the second loop, slice(0, i) and join copy i elements each time: also O(n²). Both loops are quadratic; the total is O(n²).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'javascript', 'Coûts cachés', 'Quelle est la complexité de `build(n)` ?', 'function build(n) {
  let s = "";
  const parts = [];
  for (let i = 0; i < n; i++) {
    parts.unshift(String(i % 10));   // add at the front
  }
  for (let i = 0; i < n; i++) {
    s = parts.slice(0, i).join("").length + s.slice(0, 1);
  }
  return s;
}', '["O(n)", "O(n log n)", "O(n²) pour la première boucle seulement", "O(n²) : les deux boucles sont quadratiques"]', 'D', 'Que fait `unshift` aux autres éléments ? Combien coûte `slice(0, i).join("")` ?', 'unshift décale tous les éléments existants d''une case : 1 + 2 + … + n = O(n²). Dans la deuxième boucle, slice(0, i) et join copient i éléments à chaque tour : aussi O(n²). Les deux boucles sont quadratiques ; le total est O(n²).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'javascript', 'Memoized stairs', 'For one call `ways(n, k)` on an empty memo, what is the time complexity?', 'const memo = new Map();
function ways(n, k) {        // number of ways to climb n steps, 1..k at a time
  if (n === 0) return 1;
  if (n < 0) return 0;
  const key = n + "," + k;
  if (memo.has(key)) return memo.get(key);
  let total = 0;
  for (let s = 1; s <= k; s++) total += ways(n - s, k);
  memo.set(key, total);
  return total;
}', '["O(kⁿ)", "O(n·k)", "O(n + k)", "O(n²·k)"]', 'B', 'k never changes. How many different keys can be stored, and what does each one cost the first time?', 'k is fixed, so there are at most n + 1 distinct states (n, n-1, …, 0). Each is computed once with a loop of k calls (later calls hit the memo in O(1)): O(n·k). Without the memo it would be exponential, O(kⁿ).', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'javascript', 'Escaliers mémoïsés', 'Pour un appel `ways(n, k)` avec un memo vide, quelle est la complexité ?', 'const memo = new Map();
function ways(n, k) {        // number of ways to climb n steps, 1..k at a time
  if (n === 0) return 1;
  if (n < 0) return 0;
  const key = n + "," + k;
  if (memo.has(key)) return memo.get(key);
  let total = 0;
  for (let s = 1; s <= k; s++) total += ways(n - s, k);
  memo.set(key, total);
  return total;
}', '["O(kⁿ)", "O(n·k)", "O(n + k)", "O(n²·k)"]', 'B', 'k ne change jamais. Combien de clés différentes peuvent être stockées, et combien coûte chacune la première fois ?', 'k est fixe, donc il y a au plus n + 1 états distincts (n, n-1, …, 0). Chacun est calculé une fois avec une boucle de k appels (les appels suivants trouvent le memo en O(1)) : O(n·k). Sans memo ce serait exponentiel, O(kⁿ).', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'javascript', 'Shared counter', 'Each counter should count on its own, starting from its id: `cs[0].next()` → 1, `cs[1].next()` → 2. Instead it prints `4 5 0`. Why?', 'function makeCounters(n) {
  const counters = [];
  for (var i = 0; i < n; i++) {
    counters.push({ id: i, next: () => ++i });
  }
  return counters;
}
const cs = makeCounters(3);
console.log(cs[0].next(), cs[1].next(), cs[0].id);', '["`++i` should be `i++`", "Objects can''t contain arrow functions", "All the arrow functions close over the SAME `var i`, which is 3 after the loop, and they all increment it", "`id: i` is evaluated after the loop ends"]', 'C', 'How many variables named `i` exist with `var`? Why is `id` correct but `next` not?', '`id: i` is copied immediately (0, 1, 2), but the arrow functions capture the single function-scoped `var i`, which ends at 3. Each next() increments that shared variable: 4, then 5. Use `let` and a separate variable per counter: `let c = i; next: () => ++c`.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'javascript', 'Compteur partagé', 'Chaque compteur devrait compter seul à partir de son id : `cs[0].next()` → 1, `cs[1].next()` → 2. Ça affiche `4 5 0`. Pourquoi ?', 'function makeCounters(n) {
  const counters = [];
  for (var i = 0; i < n; i++) {
    counters.push({ id: i, next: () => ++i });
  }
  return counters;
}
const cs = makeCounters(3);
console.log(cs[0].next(), cs[1].next(), cs[0].id);', '["`++i` devrait être `i++`", "Un objet ne peut pas contenir de fonction fléchée", "Toutes les fonctions fléchées capturent le MÊME `var i`, qui vaut 3 après la boucle, et l''incrémentent toutes", "`id: i` est évalué après la fin de la boucle"]', 'C', 'Combien de variables `i` existent avec `var` ? Pourquoi `id` est correct mais pas `next` ?', '`id: i` est copié tout de suite (0, 1, 2), mais les fonctions fléchées capturent l''unique `var i` de la fonction, qui finit à 3. Chaque next() incrémente cette variable partagée : 4, puis 5. Utilise `let` et une variable par compteur : `let c = i; next: () => ++c`.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'javascript', 'Search forever', '`binarySearch([2, 4], 4)` never returns. What is the bug?', 'function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (arr[mid] < target) lo = mid;
    else hi = mid;
  }
  return arr[lo] === target ? lo : -1;
}', '["`hi` should start at `arr.length`", "When `arr[mid] < target`, `lo = mid` can leave `lo` unchanged (mid rounds down), so the loop never ends: it must be `lo = mid + 1`", "`Math.floor` should be `Math.ceil` in the `else` branch only", "The loop must be `while (lo <= hi)` and nothing else"]', 'B', 'Run it by hand with lo = 0, hi = 1. What is mid? What is lo after the step?', 'With lo = 0 and hi = 1, mid = 0. Since arr[0] < target, lo = mid = 0 again: no progress, infinite loop. Discarding mid itself (`lo = mid + 1`) guarantees the range shrinks every iteration.', 'algorithms', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'javascript', 'Recherche sans fin', '`binarySearch([2, 4], 4)` ne termine jamais. Quel est le bug ?', 'function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (arr[mid] < target) lo = mid;
    else hi = mid;
  }
  return arr[lo] === target ? lo : -1;
}', '["`hi` devrait commencer à `arr.length`", "Quand `arr[mid] < target`, `lo = mid` peut laisser `lo` inchangé (mid est arrondi vers le bas) : la boucle ne finit jamais, il faut `lo = mid + 1`", "Il faut `Math.ceil` seulement dans la branche `else`", "Il suffit d''écrire `while (lo <= hi)`"]', 'B', 'Déroule-le à la main avec lo = 0, hi = 1. Que vaut mid ? Et lo après le tour ?', 'Avec lo = 0 et hi = 1, mid = 0. Comme arr[0] < target, lo = mid = 0 encore : aucun progrès, boucle infinie. Exclure mid (`lo = mid + 1`) garantit que l''intervalle rétrécit à chaque tour.', 'algorithms', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'javascript', 'Clone gone wrong', 'Why is `deepClone` wrong for this object?', 'function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}
const event = { title: "Exam", date: new Date(2026, 5, 1), attendees: new Set(["ana"]), score: NaN };
const copy = deepClone(event);
console.log(typeof copy.date, copy.attendees, copy.score);', '["JSON can''t represent Dates, Sets or NaN: the Date becomes a string, the Set becomes `{}` and NaN becomes `null`", "`JSON.stringify` throws on nested objects", "`JSON.parse` returns the same object, not a copy", "It works, but it''s slow"]', 'A', 'What does JSON know about? Strings, numbers, booleans, null, arrays, plain objects…', 'JSON only has strings, finite numbers, booleans, null, arrays and plain objects. A Date is serialized as an ISO string, a Set has no enumerable properties ({}), and NaN/Infinity become null. Use `structuredClone(obj)`.', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'javascript', 'Clone raté', 'Pourquoi `deepClone` est-elle fausse pour cet objet ?', 'function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}
const event = { title: "Exam", date: new Date(2026, 5, 1), attendees: new Set(["ana"]), score: NaN };
const copy = deepClone(event);
console.log(typeof copy.date, copy.attendees, copy.score);', '["JSON ne sait pas représenter les Date, Set ou NaN : la date devient une chaîne, le Set devient `{}` et NaN devient `null`", "`JSON.stringify` plante sur les objets imbriqués", "`JSON.parse` renvoie le même objet, pas une copie", "Ça marche, mais c''est lent"]', 'A', 'Que connaît JSON ? Chaînes, nombres, booléens, null, tableaux, objets simples…', 'JSON ne connaît que les chaînes, les nombres finis, les booléens, null, les tableaux et les objets simples. Une Date devient une chaîne ISO, un Set n''a pas de propriétés énumérables ({}), et NaN/Infinity deviennent null. Utilise `structuredClone(obj)`.', 'objects', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'php', 'Loose comparison', 'What does this code print? (write the 6 values, e.g. `bool(true) bool(false) …`)', 'var_dump(0 == "a", "1" == "01", "10" == "1e1", 100 == "1e2", null == false, "abc" === "ABC");', NULL, 'bool(false)
bool(true)
bool(true)
bool(true)
bool(true)
bool(false)', 'In PHP 8, a number and a non-numeric string are compared as strings. Two numeric strings are compared as numbers.', 'PHP 8: 0 == "a" compares "0" with "a": false. "1" and "01" are numeric strings, compared as numbers: true. "10" == "1e1": both numeric (10): true. 100 == "1e2": true. null == false: true. === is case-sensitive: false.', 'comparison', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'php', 'Comparaison souple', 'Qu''affiche ce code ? (écris les 6 valeurs, ex. `bool(true) bool(false) …`)', 'var_dump(0 == "a", "1" == "01", "10" == "1e1", 100 == "1e2", null == false, "abc" === "ABC");', NULL, 'bool(false)
bool(true)
bool(true)
bool(true)
bool(true)
bool(false)', 'En PHP 8, un nombre et une chaîne non numérique se comparent comme des chaînes. Deux chaînes numériques se comparent comme des nombres.', 'PHP 8 : 0 == "a" compare "0" et "a" : false. "1" et "01" sont numériques, comparées comme nombres : true. "10" == "1e1" : toutes deux valent 10 : true. 100 == "1e2" : true. null == false : true. === respecte la casse : false.', 'comparison', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'php', 'Who gets which key?', 'What does this code print?', '$a = [5 => "x", "y"];
$a[] = "z";
$a["2"] = "w";
$a[] = "v";
echo count($a), " ", implode(",", array_keys($a));', NULL, '5 5,6,7,2,8', '`[]` appends with key = (largest integer key so far) + 1. Numeric string keys like "2" become integers.', '"x" has key 5, so "y" gets 6 and "z" gets 7. "2" is converted to the integer key 2. The last append uses max key + 1 = 8. 5 elements, keys 5,6,7,2,8 in insertion order.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'php', 'Qui reçoit quelle clé ?', 'Qu''affiche ce code ?', '$a = [5 => "x", "y"];
$a[] = "z";
$a["2"] = "w";
$a[] = "v";
echo count($a), " ", implode(",", array_keys($a));', NULL, '5 5,6,7,2,8', '`[]` ajoute avec la clé = (plus grande clé entière) + 1. Les clés chaînes numériques comme "2" deviennent des entiers.', '"x" a la clé 5, donc "y" reçoit 6 et "z" 7. "2" devient la clé entière 2. Le dernier ajout prend max + 1 = 8. 5 éléments, clés 5,6,7,2,8 dans l''ordre d''insertion.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'php', 'Precedence trap', 'What does this code print?', '$s = "Hello";
$t = $s . " " . strtoupper(substr($s, -3)) . strlen($s) + 1;
echo $t;', NULL, 'Hello LLO6', 'In PHP 8, `+` binds tighter than `.`.', 'PHP 8 evaluates `strlen($s) + 1` first (6), then concatenates: "Hello" . " " . "LLO" . 6. (In PHP 7 the concatenation happened first, which is why this changed.)', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'php', 'Piège de priorité', 'Qu''affiche ce code ?', '$s = "Hello";
$t = $s . " " . strtoupper(substr($s, -3)) . strlen($s) + 1;
echo $t;', NULL, 'Hello LLO6', 'En PHP 8, `+` est prioritaire sur `.`.', 'PHP 8 calcule d''abord `strlen($s) + 1` (6), puis concatène : "Hello" . " " . "LLO" . 6. (En PHP 7 la concaténation passait d''abord, d''où ce changement.)', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'php', 'Divide and compare', 'What does this code print?', 'echo 7 / 2, " ", intdiv(7, 2), " ", -7 % 3, " ", 7 <=> 3, " ", round(2.5), " ", (int) "12abc";', NULL, '3.5 3 -1 1 3 12', '`/` always gives a float when the result isn''t whole. `%` keeps the sign of the left operand. round() rounds halves away from zero.', '7 / 2 = 3.5; intdiv truncates: 3; -7 % 3 = -1 (sign of the dividend); 7 <=> 3 = 1; round(2.5) = 3; (int)"12abc" reads the leading digits: 12.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'php', 'Diviser et comparer', 'Qu''affiche ce code ?', 'echo 7 / 2, " ", intdiv(7, 2), " ", -7 % 3, " ", 7 <=> 3, " ", round(2.5), " ", (int) "12abc";', NULL, '3.5 3 -1 1 3 12', '`/` donne un flottant quand le résultat n''est pas entier. `%` garde le signe de l''opérande de gauche. round() arrondit les moitiés en s''éloignant de zéro.', '7 / 2 = 3.5 ; intdiv tronque : 3 ; -7 % 3 = -1 (signe du dividende) ; 7 <=> 3 = 1 ; round(2.5) = 3 ; (int)"12abc" lit les chiffres du début : 12.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'en', 'php', 'Is it set?', 'Which statement is true?', NULL, '["`isset($x)` is `true` when `$x = null`", "`empty(\"0\")` is `false`", "`isset($a[\"k\"])` is `false` when `$a[\"k\"] = null`, but `array_key_exists(\"k\", $a)` is `true`", "`empty([])` throws an error"]', 'C', 'isset() checks "exists AND is not null". empty() treats "0" as empty.', 'isset returns false for null values, even if the key exists; array_key_exists only checks the key. empty("0") is true (a famous trap) and empty([]) is true, not an error.', 'isset / empty', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'fr', 'php', 'Défini ou pas ?', 'Quelle affirmation est vraie ?', NULL, '["`isset($x)` vaut `true` quand `$x = null`", "`empty(\"0\")` vaut `false`", "`isset($a[\"k\"])` vaut `false` quand `$a[\"k\"] = null`, mais `array_key_exists(\"k\", $a)` vaut `true`", "`empty([])` lève une erreur"]', 'C', 'isset() vérifie « existe ET n''est pas null ». empty() considère "0" comme vide.', 'isset renvoie false pour une valeur null, même si la clé existe ; array_key_exists ne regarde que la clé. empty("0") vaut true (un piège célèbre) et empty([]) vaut true, sans erreur.', 'isset / empty', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'en', 'php', 'Passing to a function', 'What happens when you pass an array and an object to a function that modifies them?', NULL, '["Arrays are passed by reference, like objects", "Arrays are passed by value (copied when modified); objects are passed as handles to the same object", "Both arrays and objects are deep-copied", "Neither can be modified inside a function"]', 'B', 'Try `function f($a) { $a[] = 1; }` and look at the original array.', 'Arrays have value semantics (copy-on-write): the function changes its own copy. Objects are handles: the function changes the same object. To modify the caller''s array, use `&$arr`.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'easy', 'fr', 'php', 'Passer à une fonction', 'Que se passe-t-il quand on passe un tableau et un objet à une fonction qui les modifie ?', NULL, '["Les tableaux sont passés par référence, comme les objets", "Les tableaux sont passés par valeur (copiés s''ils sont modifiés) ; les objets sont des poignées vers le même objet", "Tableaux et objets sont copiés en profondeur", "Aucun des deux ne peut être modifié dans une fonction"]', 'B', 'Essaie `function f($a) { $a[] = 1; }` et regarde le tableau d''origine.', 'Les tableaux se comportent comme des valeurs (copie à l''écriture) : la fonction modifie sa propre copie. Les objets sont des poignées : la fonction modifie le même objet. Pour modifier le tableau de l''appelant, utilise `&$arr`.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'en', 'php', 'Flip it', 'With n = count($a) and m = count($b), what is the time complexity?', 'function commonCount(array $a, array $b): int {
    $set = array_flip($b);          // values of $b become keys
    $count = 0;
    foreach ($a as $x) {
        if (isset($set[$x])) $count++;
    }
    return $count;
}', '["O(n·m)", "O(n²)", "O(n log m)", "O(n + m)"]', 'D', 'What does array_flip cost? And a key lookup with isset?', 'array_flip goes through $b once: O(m). Each isset on an array key is a hash lookup, O(1) on average, done n times: O(n). Total O(n + m). With in_array instead of isset it would be O(n·m).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'fr', 'php', 'Retourne-le', 'Avec n = count($a) et m = count($b), quelle est la complexité ?', 'function commonCount(array $a, array $b): int {
    $set = array_flip($b);          // values of $b become keys
    $count = 0;
    foreach ($a as $x) {
        if (isset($set[$x])) $count++;
    }
    return $count;
}', '["O(n·m)", "O(n²)", "O(n log m)", "O(n + m)"]', 'D', 'Combien coûte array_flip ? Et une recherche de clé avec isset ?', 'array_flip parcourt $b une fois : O(m). Chaque isset sur une clé est une recherche par hachage, O(1) en moyenne, faite n fois : O(n). Total O(n + m). Avec in_array au lieu de isset, ce serait O(n·m).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'en', 'php', 'Times three', 'What is the time complexity of `powers($n)`?', 'function powers(int $n): int {
    $steps = 0;
    for ($i = 1; $i < $n; $i *= 3) {
        $steps++;
    }
    return $steps;
}', '["O(log n)", "O(n)", "O(n / 3)", "O(√n)"]', 'A', 'i takes the values 1, 3, 9, 27… How many before reaching n?', 'i is multiplied by 3 at each step, so it reaches n after about log₃ n steps: O(log n). O(n / 3) would be a loop where i += 3.', 'loops', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'fr', 'php', 'Fois trois', 'Quelle est la complexité de `powers($n)` ?', 'function powers(int $n): int {
    $steps = 0;
    for ($i = 1; $i < $n; $i *= 3) {
        $steps++;
    }
    return $steps;
}', '["O(log n)", "O(n)", "O(n / 3)", "O(√n)"]', 'A', 'i prend les valeurs 1, 3, 9, 27… Combien avant d''atteindre n ?', 'i est multiplié par 3 à chaque tour, il atteint n après environ log₃ n tours : O(log n). O(n / 3) correspondrait à i += 3.', 'loops', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'en', 'php', 'Found at zero', '`startsWithHttp("http://example.com")` returns false. Why?', 'function startsWithHttp(string $url): bool {
    if (strpos($url, "http")) {
        return true;
    }
    return false;
}
var_dump(startsWithHttp("http://example.com"));', '["strpos is case-insensitive", "strpos returns 0 (the position) when the text is at the start, and 0 is falsy: compare with `!== false`, or use `str_starts_with`", "strpos needs the arguments in the other order", "The function must return `int`"]', 'B', 'What does strpos return when it finds the text at the very beginning?', 'strpos returns the position of the match. At the start, that''s 0, which `if` treats as false. Use `strpos($url, "http") === 0` or, in PHP 8, `str_starts_with($url, "http")`.', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'fr', 'php', 'Trouvé en zéro', '`startsWithHttp("http://example.com")` renvoie false. Pourquoi ?', 'function startsWithHttp(string $url): bool {
    if (strpos($url, "http")) {
        return true;
    }
    return false;
}
var_dump(startsWithHttp("http://example.com"));', '["strpos ignore la casse", "strpos renvoie 0 (la position) quand le texte est au début, et 0 est faux : compare avec `!== false`, ou utilise `str_starts_with`", "strpos attend les arguments dans l''autre ordre", "La fonction doit renvoyer un `int`"]', 'B', 'Que renvoie strpos quand il trouve le texte tout au début ?', 'strpos renvoie la position trouvée. Au début, c''est 0, que `if` considère comme faux. Utilise `strpos($url, "http") === 0` ou, en PHP 8, `str_starts_with($url, "http")`.', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'en', 'php', 'Sorted… what?', 'This code should print 5 but prints nothing (and a warning). Why?', '$scores = [12, 5, 30];
$sorted = sort($scores);
echo $sorted[0];', '["`sort()` sorts the array in place and returns `true`, not the sorted array", "`sort()` sorts in descending order", "`$sorted[0]` is the last element", "`sort()` only works on strings"]', 'A', 'Read the return type of sort() in the PHP manual.', 'sort() modifies $scores itself (passed by reference) and returns a boolean. $sorted is true, and true[0] is null. Use `sort($scores); echo $scores[0];`.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'easy', 'fr', 'php', 'Trié… quoi ?', 'Ce code devrait afficher 5 mais n''affiche rien (et un avertissement). Pourquoi ?', '$scores = [12, 5, 30];
$sorted = sort($scores);
echo $sorted[0];', '["`sort()` trie le tableau sur place et renvoie `true`, pas le tableau trié", "`sort()` trie par ordre décroissant", "`$sorted[0]` est le dernier élément", "`sort()` ne marche que sur des chaînes"]', 'A', 'Lis le type de retour de sort() dans le manuel PHP.', 'sort() modifie $scores lui-même (passé par référence) et renvoie un booléen. $sorted vaut true, et true[0] vaut null. Écris `sort($scores); echo $scores[0];`.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'php', 'Dangling reference', 'What does this code print?', '$arr = [1, 2, 3];
foreach ($arr as &$v) {
    $v *= 2;
}
foreach ($arr as $v) {
}
echo implode(",", $arr);', NULL, '2,4,4', 'After the first loop, `$v` is still a reference to the last element. What does the second loop write into `$v`?', 'After loop 1, $arr is [2,4,6] and $v still points to $arr[2]. Loop 2 assigns each element to $v, i.e. to $arr[2]: 2, then 4, then $arr[2] itself (4). Result 2,4,4. Always `unset($v)` after a by-reference foreach.', 'references', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'php', 'Référence pendante', 'Qu''affiche ce code ?', '$arr = [1, 2, 3];
foreach ($arr as &$v) {
    $v *= 2;
}
foreach ($arr as $v) {
}
echo implode(",", $arr);', NULL, '2,4,4', 'Après la première boucle, `$v` est toujours une référence vers le dernier élément. Qu''écrit la deuxième boucle dans `$v` ?', 'Après la boucle 1, $arr vaut [2,4,6] et $v pointe encore vers $arr[2]. La boucle 2 affecte chaque élément à $v, donc à $arr[2] : 2, puis 4, puis $arr[2] lui-même (4). Résultat 2,4,4. Fais toujours `unset($v)` après un foreach par référence.', 'references', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'php', '+ versus array_merge', 'What does this code print?', '$a = [1 => "a", 2 => "b"];
$b = [2 => "c", 3 => "d"];
$plus = $a + $b;
$merged = array_merge($a, $b);
echo implode("", $plus), " ", implode(",", array_keys($merged)), " ", count(array_unique([1, "1", 1.0, true]));', NULL, 'abd 0,1,2,3 1', '`+` keeps the left value when a key exists in both. array_merge renumbers integer keys. array_unique compares values as strings.', '$a + $b keeps a, b and only adds key 3 (d): "abd". array_merge renumbers integer keys from 0: 0,1,2,3. array_unique compares (string) values: 1, "1", 1.0 and true all become "1": 1 element left.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'php', '+ ou array_merge', 'Qu''affiche ce code ?', '$a = [1 => "a", 2 => "b"];
$b = [2 => "c", 3 => "d"];
$plus = $a + $b;
$merged = array_merge($a, $b);
echo implode("", $plus), " ", implode(",", array_keys($merged)), " ", count(array_unique([1, "1", 1.0, true]));', NULL, 'abd 0,1,2,3 1', '`+` garde la valeur de gauche si la clé existe des deux côtés. array_merge renumérote les clés entières. array_unique compare les valeurs comme des chaînes.', '$a + $b garde a, b et n''ajoute que la clé 3 (d) : "abd". array_merge renumérote les clés entières depuis 0 : 0,1,2,3. array_unique compare les valeurs en chaîne : 1, "1", 1.0 et true deviennent tous "1" : il reste 1 élément.', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'php', 'use, &use and fn', 'What does this code print?', '$total = 10;
$byValue = function ($x) use ($total) { return $x + $total; };
$byRef = function ($x) use (&$total) { $total += $x; return $total; };
$arrow = fn($x) => $x * $total;
$total = 100;
echo $byValue(1), " ", $byRef(5), " ", $arrow(2), " ", $total;', NULL, '11 105 20 105', '`use ($x)` copies the value when the closure is CREATED. `fn` captures by value too, at creation.', '$byValue captured 10: 1 + 10 = 11. $byRef shares $total (now 100): 105, and $total becomes 105. The arrow function captured 10 when it was created: 2 × 10 = 20. Finally $total is 105.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'php', 'use, &use et fn', 'Qu''affiche ce code ?', '$total = 10;
$byValue = function ($x) use ($total) { return $x + $total; };
$byRef = function ($x) use (&$total) { $total += $x; return $total; };
$arrow = fn($x) => $x * $total;
$total = 100;
echo $byValue(1), " ", $byRef(5), " ", $arrow(2), " ", $total;', NULL, '11 105 20 105', '`use ($x)` copie la valeur à la CRÉATION de la closure. `fn` capture aussi par valeur, à la création.', '$byValue a capturé 10 : 1 + 10 = 11. $byRef partage $total (qui vaut 100) : 105, et $total devient 105. La fonction fléchée a capturé 10 à sa création : 2 × 10 = 20. Enfin $total vaut 105.', 'closures', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'en', 'php', 'Static memory', 'What does this code print?', 'function visit() {
    static $count = 0;
    $count++;
    return $count;
}
class Counter {
    public static int $made = 0;
    public function __construct() { self::$made++; }
}
visit(); visit();
new Counter(); new Counter(); $c = new Counter();
echo visit(), " ", Counter::$made, " ", $c::$made;', NULL, '3 3 3', 'A `static` variable inside a function keeps its value between calls. A static property belongs to the class, not to each object.', 'visit() was called twice, so the third call returns 3. Three objects were created, each incrementing the class-wide counter: 3, the same value seen through $c::$made.', 'static', NULL, NULL, NULL, 'active', 'seed', 1791475200);
